}
foreach($name in @('systemPowerShellPath','retainedNodePath','installRoot','startupStateDirectory','entrySha256','sourceRevision')){$copy=$data|ConvertTo-Json -Compress|ConvertFrom-Json;$copy.$name='PUBLIC_WRONG';$refused=$false;try{New-OwnerCutoverCleanStartCommandData $copy|Out-Null}catch{$refused=$_.Exception.Message -ceq 'ROTATION_CUTOVER_START_PREFIX_REJECTED'};Require $refused 'CLOSED_BINDING_FIELDS';$cases+='binding'}
